  assert.deepEqual(removeLine(invoice, 'DES-HOUR'), { ok: false, error: 'NO_LINES' });
});

test('removeLine reports NOT_DRAFT for non-draft invoices', () => {
  const nonDraftInvoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'sent',
    lines: [
      { sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(nonDraftInvoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
