});

test('addLine and removeLine can chain on a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 3 });
