test('invoiceTotals with tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const lineTotal = 10 * 8500;
  const discount = Math.round(lineTotal * 5 / 100);
  const amountAfterDiscount = lineTotal - discount;
  const vat = Math.round(amountAfterDiscount * 21 / 100);
  assert.deepEqual(totals, { subtotal: lineTotal, discount, vat, total: lineTotal - discount + vat });
});
